  var result = numbers
    .%order%((%order%) => %order% % %order% == %order%)  // Keep even numbers
    .%order%((%order%) => %order% * %order%)       // Multiply by 3
    .%order%((%order%) => %order% > %order%)      // Keep numbers > 10
    .%order%()                               // Convert to List
    ;

  print(result);
}
```
